import * as THREE from 'three';

// ═══════════════════════════════════════════════════════════════════════════════════════════════
// PREMIUM WEAPON SYSTEM v2.0 — Realistic textures, detailed models, advanced animations, layered audio
// ═══════════════════════════════════════════════════════════════════════════════════════════════

// ─── Canvas Texture System ────────────────────────────────────────────────────────────────────

function createCanvasTexture(width, height, drawFn) {
    const canvas = document.createElement('canvas');
    canvas.width = width;
    canvas.height = height;
    const ctx = canvas.getContext('2d');
    drawFn(ctx, width, height);
    const texture = new THREE.CanvasTexture(canvas);
    texture.wrapS = THREE.RepeatWrapping;
    texture.wrapT = THREE.RepeatWrapping;
    texture.minFilter = THREE.LinearMipmapLinearFilter;
    texture.magFilter = THREE.LinearFilter;
    texture.generateMipmaps = true;
    return texture;
}

// ── Premium Brushed Metal (directional, multi-pass) ───────────────────────────────────────────

function createMetalTexture(baseColor = '#7a8590') {
    return createCanvasTexture(512, 512, (ctx, w, h) => {
        // Base + subtle color variation
        ctx.fillStyle = baseColor;
        ctx.fillRect(0, 0, w, h);
        for (let i = 0; i < 3000; i++) {
            const x = Math.random() * w;
            const y = Math.random() * h;
            ctx.fillStyle = `rgba(${Math.random() > 0.5 ? 40 : 0},${Math.random() > 0.5 ? 40 : 0},${Math.random() > 0.5 ? 40 : 0},${Math.random() * 0.04})`;
            ctx.fillRect(x, y, 2, 2);
        }

        // Fine directional brush strokes
        for (let y = 0; y < h; y += 1.5) {
            const brightness = 0.92 + Math.random() * 0.16;
            ctx.strokeStyle = `rgba(${Math.floor(128 * brightness)},${Math.floor(128 * brightness)},${Math.floor(128 * brightness)},${0.03 + Math.random() * 0.06})`;
            ctx.lineWidth = 0.5 + Math.random();
            ctx.beginPath();
            ctx.moveTo(0, y + (Math.random() - 0.5) * 2);
            ctx.lineTo(w, y + (Math.random() - 0.5) * 3);
            ctx.stroke();
        }

        // Deep scratches
        for (let i = 0; i < 20; i++) {
            const y = Math.random() * h;
            ctx.strokeStyle = `rgba(0,0,0,${0.08 + Math.random() * 0.15})`;
            ctx.lineWidth = 0.5 + Math.random() * 1.5;
            ctx.beginPath();
            ctx.moveTo(0, y);
            let cx = 0;
            while (cx < w) {
                cx += 30 + Math.random() * 60;
                ctx.lineTo(cx, y + (Math.random() - 0.5) * 8);
            }
            ctx.stroke();
        }

        // Hot spots (oxidation/corrosion)
        for (let i = 0; i < 8; i++) {
            const x = Math.random() * w;
            const y = Math.random() * h;
            const r = 10 + Math.random() * 30;
            const grad = ctx.createRadialGradient(x, y, 0, x, y, r);
            grad.addColorStop(0, `rgba(80,60,40,${0.03 + Math.random() * 0.05})`);
            grad.addColorStop(1, 'transparent');
            ctx.fillStyle = grad;
            ctx.fillRect(x - r, y - r, r * 2, r * 2);
        }
    });
}

// ── Dark Metal (for polymer/coated parts) ─────────────────────────────────────────────────────

function createDarkMetalTexture(baseColor = '#1a1f25') {
    return createCanvasTexture(512, 512, (ctx, w, h) => {
        ctx.fillStyle = baseColor;
        ctx.fillRect(0, 0, w, h);
        // Fine matte texture (like anodized aluminum or polymer)
        for (let i = 0; i < 5000; i++) {
            const x = Math.random() * w;
            const y = Math.random() * h;
            const v = Math.random() * 20 - 10;
            ctx.fillStyle = `rgba(${v > 0 ? v : 0},${v > 0 ? v : 0},${v > 0 ? v : 0},${0.1})`;
            ctx.fillRect(x, y, 1, 1);
        }
        // Horizontal micro-lines (CNC machining marks)
        for (let y = 0; y < h; y += 3) {
            ctx.strokeStyle = `rgba(255,255,255,${Math.random() * 0.02})`;
            ctx.lineWidth = 0.5;
            ctx.beginPath();
            ctx.moveTo(0, y);
            ctx.lineTo(w, y + Math.random() * 2 - 1);
            ctx.stroke();
        }
    });
}

// ── Premium Wood (quarter-sawn figure pattern) ────────────────────────────────────────────────

function createWoodTexture(baseColor = '#5a3a20') {
    return createCanvasTexture(512, 512, (ctx, w, h) => {
        ctx.fillStyle = baseColor;
        ctx.fillRect(0, 0, w, h);

        // Base color variation
        for (let i = 0; i < 1000; i++) {
            const x = Math.random() * w;
            const y = Math.random() * h;
            ctx.fillStyle = `rgba(${Math.random() > 0.5 ? 30 : 0},${Math.random() > 0.5 ? 15 : 0},${Math.random() > 0.5 ? 0 : 0},${Math.random() * 0.06})`;
            ctx.fillRect(x, y, 3, 3);
        }

        // Wood grain lines with figure patterns
        for (let row = 0; row < 40; row++) {
            const baseY = (row / 40) * h;
            const darkness = 0.08 + Math.random() * 0.18;
            ctx.strokeStyle = `rgba(0,0,0,${darkness})`;
            ctx.lineWidth = 1 + Math.random() * 3;
            ctx.beginPath();
            ctx.moveTo(0, baseY);
            // Wavy grain with figure patterns
            for (let x = 0; x <= w; x += 8) {
                const wave = Math.sin(x * 0.01 + row) * 8 + Math.sin(x * 0.03 + row * 0.5) * 4;
                ctx.lineTo(x, baseY + wave);
            }
            ctx.stroke();
        }

        // Growth rings (annual rings)
        for (let i = 0; i < 5; i++) {
            const cx = Math.random() * w;
            const cy = Math.random() * h;
            ctx.strokeStyle = `rgba(60,30,10,${0.06 + Math.random() * 0.08})`;
            ctx.lineWidth = 1;
            ctx.beginPath();
            for (let a = 0; a < Math.PI * 2; a += 0.1) {
                const r = 20 + a * 8 + Math.sin(a * 3) * 5;
                ctx.lineTo(cx + Math.cos(a) * r * 0.5, cy + r);
            }
            ctx.stroke();
        }

        // Knots
        for (let i = 0; i < 3; i++) {
            const kx = Math.random() * w;
            const ky = Math.random() * h;
            const grad = ctx.createRadialGradient(kx, ky, 0, kx, ky, 15);
            grad.addColorStop(0, 'rgba(30,15,5,0.3)');
            grad.addColorStop(0.5, 'rgba(60,35,15,0.15)');
            grad.addColorStop(1, 'transparent');
            ctx.fillStyle = grad;
            ctx.beginPath();
            ctx.arc(kx, ky, 15, 0, Math.PI * 2);
            ctx.fill();
        }
    });
}

// ── Polymer / Rubber texture (for grips, stocks) ──────────────────────────────────────────────

function createPolymerTexture(baseColor = '#12141a') {
    return createCanvasTexture(512, 512, (ctx, w, h) => {
        ctx.fillStyle = baseColor;
        ctx.fillRect(0, 0, w, h);
        // Fine stippled rubber texture
        for (let i = 0; i < 20000; i++) {
            const x = Math.random() * w;
            const y = Math.random() * h;
            const v = Math.random() * 30 - 15;
            const alpha = 0.05 + Math.random() * 0.12;
            ctx.fillStyle = `rgba(${v > 0 ? v : 0},${v > 0 ? v : 0},${v > 0 ? v : 0},${alpha})`;
            ctx.fillRect(x, y, 1, 1);
        }
        // Diamond grip pattern
        ctx.strokeStyle = 'rgba(0,0,0,0.15)';
        ctx.lineWidth = 1;
        for (let y = 0; y < h; y += 12) {
            for (let x = (y / 12) % 2 * 12; x < w; x += 24) {
                ctx.beginPath();
                ctx.moveTo(x, y - 6);
                ctx.lineTo(x + 6, y);
                ctx.lineTo(x, y + 6);
                ctx.lineTo(x - 6, y);
                ctx.closePath();
                ctx.stroke();
            }
        }
    });
}

// ── Slide Markings / Engravings ────────────────────────────────────────────────────────────────

function createEngravingTexture() {
    return createCanvasTexture(256, 64, (ctx, w, h) => {
        ctx.fillStyle = 'rgba(0,0,0,0)';
        ctx.fillRect(0, 0, w, h);
        // Simulated serial number lines
        ctx.strokeStyle = 'rgba(0,0,0,0.3)';
        ctx.lineWidth = 1;
        for (let i = 0; i < 12; i++) {
            const x = 10 + i * 18;
            ctx.beginPath();
            ctx.moveTo(x, h * 0.3);
            ctx.lineTo(x + 12, h * 0.7);
            ctx.stroke();
        }
    });
}

// ── Muzzle flash texture ───────────────────────────────────────────────────────────────────────

function createMuzzleFlashTexture() {
    return createCanvasTexture(128, 128, (ctx, w, h) => {
        const grad = ctx.createRadialGradient(w / 2, h / 2, 0, w / 2, h / 2, w / 2);
        grad.addColorStop(0, 'rgba(255,255,200,1)');
        grad.addColorStop(0.2, 'rgba(255,200,50,0.8)');
        grad.addColorStop(0.5, 'rgba(255,100,20,0.4)');
        grad.addColorStop(1, 'transparent');
        ctx.fillStyle = grad;
        ctx.fillRect(0, 0, w, h);
    });
}

// ── Glow / Neon texture ────────────────────────────────────────────────────────────────────────

function createNeonTexture(color = '#6ad3ff', size = 64) {
    return createCanvasTexture(size, size, (ctx, w, h) => {
        const grad = ctx.createRadialGradient(w / 2, h / 2, 0, w / 2, h / 2, w / 2);
        grad.addColorStop(0, color);
        grad.addColorStop(0.4, color + 'cc');
        grad.addColorStop(0.7, color + '44');
        grad.addColorStop(1, 'transparent');
        ctx.fillStyle = grad;
        ctx.fillRect(0, 0, w, h);
    });
}

// ── Holster / leather texture ──────────────────────────────────────────────────────────────────

function createLeatherTexture(baseColor = '#4a3020') {
    return createCanvasTexture(512, 512, (ctx, w, h) => {
        ctx.fillStyle = baseColor;
        ctx.fillRect(0, 0, w, h);
        // Leather grain
        for (let i = 0; i < 3000; i++) {
            const x = Math.random() * w;
            const y = Math.random() * h;
            const v = Math.random() * 40 - 20;
            ctx.fillStyle = `rgba(${v > 0 ? v : 0},${v > 0 ? v * 0.6 : 0},${v > 0 ? v * 0.3 : 0},${0.08})`;
            ctx.fillRect(x, y, 2 + Math.random() * 3, 1 + Math.random() * 2);
        }
        // Stitching lines
        ctx.strokeStyle = 'rgba(180,150,100,0.2)';
        ctx.lineWidth = 2;
        ctx.setLineDash([6, 6]);
        ctx.strokeRect(20, 20, w - 40, h - 40);
        ctx.setLineDash([]);
    });
}

// ── Copper / Brass texture ─────────────────────────────────────────────────────────────────────

function createBrassTexture() {
    return createCanvasTexture(256, 256, (ctx, w, h) => {
        ctx.fillStyle = '#b5a040';
        ctx.fillRect(0, 0, w, h);
        for (let i = 0; i < 2000; i++) {
            const x = Math.random() * w;
            const y = Math.random() * h;
            const v = Math.random() * 30 - 15;
            ctx.fillStyle = `rgba(${v > 0 ? v : 0},${v > 0 ? v * 0.8 : 0},${v > 0 ? v * 0.3 : 0},0.1)`;
            ctx.fillRect(x, y, 2, 2);
        }
    });
}

