export class WeaponAnimation {
    constructor() {
        this.time = 0;
        this.recoilKick = 0;          // 0→1→0 — quick kick back
        this.recoilRecovery = 0;       // smooth recovery
        this.recoilAngle = 0;          // upward tilt from recoil
        this.muzzleFlash = 0;          // 0→1→0 — muzzle flash intensity
        this.bobPhase = 0;             // breathing bob
        this.bobAmount = 0;            // controlled by movement
        this.swayX = 0;                // mouse sway
        this.swayY = 0;                // mouse sway
        this.swayTargetX = 0;
        this.swayTargetY = 0;
        this.reloadProgress = -1;      // -1 = no reload, 0-1 = in progress
        this.reloadStartTime = 0;
        this.reloadDuration = 2.0;
        this.hitMarker = 0;            // hit marker flash
        this.lastShotTime = 0;
        this.heatGlow = 0;             // barrel heat glow
    }

    update(delta, isShooting, isMoving, mouseDx, mouseDy) {
        this.time += delta;

        // ── Recoil ──
        if (isShooting && (this.time - this.lastShotTime) < 0.15) {
            this.recoilKick = Math.min(1, this.recoilKick + delta * 15);
            this.recoilRecovery = 0;
            this.lastShotTime = this.time;
            this.muzzleFlash = 1;
            this.heatGlow = Math.min(1, this.heatGlow + delta * 3);
        }

        // Recoil recovery
        if (this.recoilKick > 0) {
            this.recoilRecovery += delta * 6;
            if (this.recoilRecovery >= 1) {
                this.recoilRecovery = 1;
                this.recoilKick = 0;
            }
        }
        // Combined recoil angle: kick + smooth recovery
        this.recoilAngle = this.recoilKick * 0.15 + (1 - this.recoilRecovery) * 0.1;

        // Muzzle flash fade
        if (this.muzzleFlash > 0) {
            this.muzzleFlash = Math.max(0, this.muzzleFlash - delta * 12);
        }

        // ── Idle breathing bob ──
        if (!isShooting) {
            this.bobPhase += delta * 0.8;
            this.bobAmount = isMoving ? 0.012 : 0.006;
        }

        // ── Sway (mouse-driven) ──
        this.swayTargetX += (mouseDx * 0.003 - this.swayTargetX) * delta * 5;
        this.swayTargetY += (mouseDy * 0.003 - this.swayTargetY) * delta * 5;
        this.swayX += (this.swayTargetX - this.swayX) * delta * 4;
        this.swayY += (this.swayTargetY - this.swayY) * delta * 4;

        // ── Reload ──
        if (this.reloadProgress >= 0) {
            this.reloadProgress += delta / this.reloadDuration;
            if (this.reloadProgress >= 1) {
                this.reloadProgress = -1;
            }
        }

        // ── Heat glow fade ──
        if (!isShooting) {
            this.heatGlow *= Math.max(0, 1 - delta * 0.3);
        }

        // ── Hit marker ──
        if (this.hitMarker > 0) {
            this.hitMarker -= delta * 5;
        }
    }

    triggerRecoil() {
        this.recoilKick = 1;
        this.recoilRecovery = 0;
        this.muzzleFlash = 1;
        this.lastShotTime = this.time;
        this.heatGlow = Math.min(1, this.heatGlow + 0.2);
    }

    triggerReload(duration = 2.0) {
        this.reloadProgress = 0;
        this.reloadStartTime = this.time;
        this.reloadDuration = duration;
    }

    applyToMesh(mesh, weaponType) {
        if (!mesh) return;
        const bob = Math.sin(this.bobPhase) * this.bobAmount;
        const swayX = this.swayX * 0.025;
        const swayY = Math.abs(this.swayY) * 0.015;

        // Recoil: rotate up (negative X), push back slightly
        const baseRot = mesh.userData.baseRotation || new THREE.Euler(0, 0, 0);
        mesh.rotation.set(
            baseRot.x + this.recoilAngle * Math.cos(this.time * 15), // kick with vibration
            baseRot.y + this.swayX,
            baseRot.z + this.swayY * 0.3
        );
        mesh.position.y += bob;
        mesh.position.x += swayX;

        // Heat glow on barrel
        if (this.heatGlow > 0.1 && weaponType !== 'bow' && weaponType !== 'knife' && weaponType !== 'fists') {
            mesh.traverse((child) => {
                if (child.isMesh && child.material) {
                    if (!child.userData.originalEmissive) {
                        child.userData.originalEmissive = child.material.emissive ? child.material.emissive.getHex() : 0;
                        child.userData.originalEmissiveIntensity = child.material.emissiveIntensity || 0;
                    }
                    if (child.material.emissive) {
                        const heatColor = this.heatGlow > 0.7 ? 0xff4400 : (this.heatGlow > 0.4 ? 0xff6600 : 0xff2200);
                        child.material.emissive.setHex(heatColor);
                        child.material.emissiveIntensity = this.heatGlow * 0.3;
                    }
                }
            });
        }
    }

    reset() {
        this.time = 0;
        this.recoilKick = 0;
        this.recoilRecovery = 0;
        this.recoilAngle = 0;
        this.muzzleFlash = 0;
        this.bobPhase = 0;
        this.bobAmount = 0;
        this.swayX = 0;
        this.swayY = 0;
        this.swayTargetX = 0;
        this.swayTargetY = 0;
        this.reloadProgress = -1;
        this.hitMarker = 0;
        this.heatGlow = 0;
    }
}

// ═══════════════════════════════════════════════════════════════════════════════════════════════
// PROCEDURAL GUNSHOT AUDIO SYSTEM
// ═══════════════════════════════════════════════════════════════════════════════════════════════

export function createGunshotSound(type, audioContext, volume = 0.5, position = null) {
    if (!audioContext) return null;
    const now = audioContext.currentTime;

    // Master gain for this gunshot
    const masterGain = audioContext.createGain();
    masterGain.gain.setValueAtTime(volume, now);
    masterGain.connect(audioContext.destination);

    // Add reverb
    const convolver = audioContext.createConvolver();
    const reverbGain = audioContext.createGain();
    reverbGain.gain.value = 0.15;
    // Create impulse response
    const irLength = audioContext.sampleRate * 1.5;
    const impulse = audioContext.createBuffer(2, irLength, audioContext.sampleRate);
    for (let ch = 0; ch < 2; ch++) {
        const data = impulse.getChannelData(ch);
        for (let i = 0; i < irLength; i++) {
            data[i] = (Math.random() * 2 - 1) * Math.pow(1 - i / irLength, 2);
        }
    }
    convolver.buffer = impulse;
    masterGain.connect(convolver);
    convolver.connect(reverbGain);
    reverbGain.connect(audioContext.destination);

    switch (type) {
        case 'pistol': {
            // Compact punchy report
            const t = now;
            // Transient snap
            const noise = createNoiseBuffer(audioContext, 0.06);
            const noiseSource = audioContext.createBufferSource();
            noiseSource.buffer = noise;
            const noiseGain = audioContext.createGain();
            noiseGain.gain.setValueAtTime(0.6, t);
            noiseGain.gain.exponentialRampToValueAtTime(0.001, t + 0.06);
            const bandpass = audioContext.createBiquadFilter();
            bandpass.type = 'bandpass';
            bandpass.frequency.value = 4000;
            bandpass.Q.value = 0.5;
            noiseSource.connect(bandpass);
            bandpass.connect(noiseGain);
            noiseGain.connect(masterGain);
            noiseSource.start(t);
            noiseSource.stop(t + 0.07);

            // Main body — low thump
            const osc = audioContext.createOscillator();
            osc.type = 'sine';
            osc.frequency.setValueAtTime(220, t);
            osc.frequency.exponentialRampToValueAtTime(60, t + 0.12);
            const oscGain = audioContext.createGain();
            oscGain.gain.setValueAtTime(0.5, t);
            oscGain.gain.exponentialRampToValueAtTime(0.001, t + 0.12);
            osc.connect(oscGain);
            oscGain.connect(masterGain);
            osc.start(t);
            osc.stop(t + 0.13);

            // Cylindrical crack
            const crack = createNoiseBuffer(audioContext, 0.04);
            const crackSource = audioContext.createBufferSource();
            crackSource.buffer = crack;
            const crackGain = audioContext.createGain();
            crackGain.gain.setValueAtTime(0.4, t + 0.005);
            crackGain.gain.exponentialRampToValueAtTime(0.001, t + 0.04);
            const hp = audioContext.createBiquadFilter();
            hp.type = 'highpass';
            hp.frequency.value = 2000;
            crackSource.connect(hp);
            hp.connect(crackGain);
            crackGain.connect(masterGain);
            crackSource.start(t + 0.005);
            crackSource.stop(t + 0.05);
            break;
        }

        case 'rifle': {
            const t = now;
            // Sharp crack
            const crack = createNoiseBuffer(audioContext, 0.08);
            const crackSource = audioContext.createBufferSource();
            crackSource.buffer = crack;
            const crackGain = audioContext.createGain();
            crackGain.gain.setValueAtTime(0.7, t);
            crackGain.gain.exponentialRampToValueAtTime(0.001, t + 0.08);
            const bp = audioContext.createBiquadFilter();
            bp.type = 'bandpass';
            bp.frequency.value = 3000;
            bp.Q.value = 0.8;
            crackSource.connect(bp);
            bp.connect(crackGain);
            crackGain.connect(masterGain);
            crackSource.start(t);
            crackSource.stop(t + 0.09);

            // Deep body
            const osc = audioContext.createOscillator();
            osc.type = 'sine';
            osc.frequency.setValueAtTime(180, t);
            osc.frequency.exponentialRampToValueAtTime(40, t + 0.18);
            const oscGain = audioContext.createGain();
            oscGain.gain.setValueAtTime(0.6, t);
            oscGain.gain.exponentialRampToValueAtTime(0.001, t + 0.18);
            osc.connect(oscGain);
            oscGain.connect(masterGain);
            osc.start(t);
            osc.stop(t + 0.19);

            // Sub-bass thud
            const sub = audioContext.createOscillator();
            sub.type = 'sine';
            sub.frequency.setValueAtTime(80, t);
            sub.frequency.exponentialRampToValueAtTime(25, t + 0.25);
            const subGain = audioContext.createGain();
            subGain.gain.setValueAtTime(0.35, t);
            subGain.gain.exponentialRampToValueAtTime(0.001, t + 0.25);
            sub.connect(subGain);
            subGain.connect(masterGain);
            sub.start(t);
            sub.stop(t + 0.26);

            // Trailing report
            const report = createNoiseBuffer(audioContext, 0.15);
            const reportSource = audioContext.createBufferSource();
            reportSource.buffer = report;
            const reportGain = audioContext.createGain();
            reportGain.gain.setValueAtTime(0.2, t + 0.02);
            reportGain.gain.exponentialRampToValueAtTime(0.001, t + 0.15);
            const lp = audioContext.createBiquadFilter();
            lp.type = 'lowpass';
            lp.frequency.value = 1500;
            reportSource.connect(lp);
            lp.connect(reportGain);
            reportGain.connect(masterGain);
            reportSource.start(t + 0.02);
            reportSource.stop(t + 0.16);
            break;
        }

        case 'machinegun': {
            const t = now;
            // Shorter, faster cycle
            const crack = createNoiseBuffer(audioContext, 0.04);
            const crackSource = audioContext.createBufferSource();
            crackSource.buffer = crack;
            const crackGain = audioContext.createGain();
            crackGain.gain.setValueAtTime(0.55, t);
            crackGain.gain.exponentialRampToValueAtTime(0.001, t + 0.04);
            const bp = audioContext.createBiquadFilter();
            bp.type = 'bandpass';
            bp.frequency.value = 5000;
            bp.Q.value = 0.6;
            crackSource.connect(bp);
            bp.connect(crackGain);
            crackGain.connect(masterGain);
            crackSource.start(t);
            crackSource.stop(t + 0.05);

            const osc = audioContext.createOscillator();
            osc.type = 'sawtooth';
            osc.frequency.setValueAtTime(300, t);
            osc.frequency.exponentialRampToValueAtTime(100, t + 0.06);
            const oscGain = audioContext.createGain();
            oscGain.gain.setValueAtTime(0.35, t);
            oscGain.gain.exponentialRampToValueAtTime(0.001, t + 0.06);
            const lp = audioContext.createBiquadFilter();
            lp.type = 'lowpass';
            lp.frequency.value = 2500;
            osc.connect(lp);
            lp.connect(oscGain);
            oscGain.connect(masterGain);
            osc.start(t);
            osc.stop(t + 0.07);
            break;
        }

        case 'shotgun': {
            const t = now;
            // Massive report
            const boom = createNoiseBuffer(audioContext, 0.2);
            const boomSource = audioContext.createBufferSource();
            boomSource.buffer = boom;
            const boomGain = audioContext.createGain();
            boomGain.gain.setValueAtTime(0.8, t);
            boomGain.gain.exponentialRampToValueAtTime(0.001, t + 0.2);
            const lp = audioContext.createBiquadFilter();
            lp.type = 'lowpass';
            lp.frequency.value = 3000;
            boomSource.connect(lp);
            lp.connect(boomGain);
            boomGain.connect(masterGain);
            boomSource.start(t);
            boomSource.stop(t + 0.21);

            // Deep bass thump
            const osc = audioContext.createOscillator();
            osc.type = 'sine';
            osc.frequency.setValueAtTime(120, t);
            osc.frequency.exponentialRampToValueAtTime(20, t + 0.3);
            const oscGain = audioContext.createGain();
            oscGain.gain.setValueAtTime(0.7, t);
            oscGain.gain.exponentialRampToValueAtTime(0.001, t + 0.3);
            osc.connect(oscGain);
            oscGain.connect(masterGain);
            osc.start(t);
            osc.stop(t + 0.31);

            // Pellets scatter
            for (let i = 1; i < 5; i++) {
                const pellet = createNoiseBuffer(audioContext, 0.02);
                const pSource = audioContext.createBufferSource();
                pSource.buffer = pellet;
                const pGain = audioContext.createGain();
                pGain.gain.setValueAtTime(0.15, t + i * 0.01);
                pGain.gain.exponentialRampToValueAtTime(0.001, t + i * 0.01 + 0.02);
                const hp = audioContext.createBiquadFilter();
                hp.type = 'highpass';
                hp.frequency.value = 5000 + i * 1000;
                pSource.connect(hp);
                hp.connect(pGain);
                pGain.connect(masterGain);
                pSource.start(t + i * 0.01);
                pSource.stop(t + i * 0.01 + 0.03);
            }
            break;
        }

        case 'laser': {
            const t = now;
            // Energy zAP
            const osc = audioContext.createOscillator();
            osc.type = 'sawtooth';
            osc.frequency.setValueAtTime(1200, t);
            osc.frequency.exponentialRampToValueAtTime(200, t + 0.12);
            const oscGain = audioContext.createGain();
            oscGain.gain.setValueAtTime(0.5, t);
            oscGain.gain.exponentialRampToValueAtTime(0.001, t + 0.12);
            const hp = audioContext.createBiquadFilter();
            hp.type = 'highpass';
            hp.frequency.value = 500;
            osc.connect(hp);
            hp.connect(oscGain);
            oscGain.connect(masterGain);
            osc.start(t);
            osc.stop(t + 0.13);

            // Bright initial transient
            const zap = createNoiseBuffer(audioContext, 0.05);
            const zapSource = audioContext.createBufferSource();
            zapSource.buffer = zap;
            const zapGain = audioContext.createGain();
            zapGain.gain.setValueAtTime(0.4, t);
            zapGain.gain.exponentialRampToValueAtTime(0.001, t + 0.05);
            const bp = audioContext.createBiquadFilter();
            bp.type = 'bandpass';
            bp.frequency.value = 8000;
            bp.Q.value = 2;
            zapSource.connect(bp);
            bp.connect(zapGain);
            zapGain.connect(masterGain);
            zapSource.start(t);
            zapSource.stop(t + 0.06);

            // Dying whine
            const whine = audioContext.createOscillator();
            whine.type = 'sine';
            whine.frequency.setValueAtTime(1800, t + 0.03);
            whine.frequency.exponentialRampToValueAtTime(300, t + 0.18);
            const whineGain = audioContext.createGain();
            whineGain.gain.setValueAtTime(0, t);
            whineGain.gain.linearRampToValueAtTime(0.2, t + 0.03);
            whineGain.gain.exponentialRampToValueAtTime(0.001, t + 0.18);
            whine.connect(whineGain);
            whineGain.connect(masterGain);
            whine.start(t + 0.03);
            whine.stop(t + 0.19);
            break;
        }

        case 'flamethrower': {
            const t = now;
            // Roaring fire
            const fire = createNoiseBuffer(audioContext, 0.3);
            const fireSource = audioContext.createBufferSource();
            fireSource.buffer = fire;
            fireSource.loop = true;
            const fireGain = audioContext.createGain();
            fireGain.gain.setValueAtTime(0.4, t);
            fireGain.gain.exponentialRampToValueAtTime(0.001, t + 0.3);
            const bp = audioContext.createBiquadFilter();
            bp.type = 'bandpass';
            bp.frequency.value = 800;
            bp.Q.value = 0.3;
            fireSource.connect(bp);
            bp.connect(fireGain);
            fireGain.connect(masterGain);
            fireSource.start(t);
            fireSource.stop(t + 0.31);

            // Hiss
            const hiss = createNoiseBuffer(audioContext, 0.2);
            const hissSource = audioContext.createBufferSource();
            hissSource.buffer = hiss;
            const hissGain = audioContext.createGain();
            hissGain.gain.setValueAtTime(0.2, t);
            hissGain.gain.exponentialRampToValueAtTime(0.001, t + 0.2);
            const hp = audioContext.createBiquadFilter();
            hp.type = 'highpass';
            hp.frequency.value = 3000;
            hissSource.connect(hp);
            hp.connect(hissGain);
            hissGain.connect(masterGain);
            hissSource.start(t);
            hissSource.stop(t + 0.21);
            break;
        }

        case 'bow': {
            const t = now;
            // Whoosh
            const whoosh = createNoiseBuffer(audioContext, 0.15);
            const whooshSource = audioContext.createBufferSource();
            whooshSource.buffer = whoosh;
            const whooshGain = audioContext.createGain();
            whooshGain.gain.setValueAtTime(0.3, t);
            whooshGain.gain.exponentialRampToValueAtTime(0.001, t + 0.15);
            const bp = audioContext.createBiquadFilter();
            bp.type = 'bandpass';
            bp.frequency.value = 2000;
            bp.Q.value = 1;
            whooshSource.connect(bp);
            bp.connect(whooshGain);
            whooshGain.connect(masterGain);
            whooshSource.start(t);
            whooshSource.stop(t + 0.16);

            // Twang
            const twang = audioContext.createOscillator();
            twang.type = 'triangle';
            twang.frequency.setValueAtTime(600, t);
            twang.frequency.exponentialRampToValueAtTime(200, t + 0.08);
            const twangGain = audioContext.createGain();
            twangGain.gain.setValueAtTime(0.3, t);
            twangGain.gain.exponentialRampToValueAtTime(0.001, t + 0.08);
            twang.connect(twangGain);
            twangGain.connect(masterGain);
            twang.start(t);
            twang.stop(t + 0.09);
            break;
        }

        default: { // generic / knife
            const t = now;
            const noise = createNoiseBuffer(audioContext, 0.08);
            const noiseSource = audioContext.createBufferSource();
            noiseSource.buffer = noise;
            const noiseGain = audioContext.createGain();
            noiseGain.gain.setValueAtTime(0.3, t);
            noiseGain.gain.exponentialRampToValueAtTime(0.001, t + 0.08);
            const bp = audioContext.createBiquadFilter();
            bp.type = 'bandpass';
            bp.frequency.value = 3000;
            bp.Q.value = 0.5;
            noiseSource.connect(bp);
            bp.connect(noiseGain);
            noiseGain.connect(masterGain);
            noiseSource.start(t);
            noiseSource.stop(t + 0.09);
        }
    }

    return { stop: () => { /* cleanup handled by source nodes */ } };
}

function createNoiseBuffer(audioContext, duration) {
    const rate = audioContext.sampleRate;
    const length = Math.max(1, Math.floor(rate * duration));
    const buffer = audioContext.createBuffer(1, length, rate);
    const data = buffer.getChannelData(0);
    for (let i = 0; i < length; i++) {
        data[i] = Math.random() * 2 - 1;
    }
    return buffer;
}

// ═══════════════════════════════════════════════════════════════════════════════════════════════
// MATERIAL CACHE
// ═══════════════════════════════════════════════════════════════════════════════════════════════

const sharedGeom = new Map();
const sharedMat = new Map();

function getMaterial(key, createFn) {
    if (!sharedMat.has(key)) {
        sharedMat.set(key, createFn());
    }
    return sharedMat.get(key);
}

function getGeom(key, createFn) {
    if (!sharedGeom.has(key)) {
        sharedGeom.set(key, createFn());
    }
    return sharedGeom.get(key);
}

const tmpQ = new THREE.Quaternion();
const tmpF = new THREE.Vector3(1, 0, 0);

function createPart(geometry, material, x = 0, y = 0, z = 0, rx = 0, ry = 0, rz = 0) {
    const mesh = new THREE.Mesh(geometry, material);
    mesh.position.set(x, y, z);
    mesh.rotation.set(rx, ry, rz);
    mesh.castShadow = false;
    mesh.receiveShadow = false;
    mesh.frustumCulled = false;
    return mesh;
}

function configureMeshForGameplay(mesh) {
    mesh.traverse((child) => {
        if (child.isMesh) {
            child.castShadow = false;
            child.receiveShadow = false;
            child.frustumCulled = false;
            child.renderOrder = 4;
            child.userData.ignoreDamageTint = true;
        }
    });
}

