}

function getRotationOffsets(type) {
    if (type === 'knife') return { pitch: -Math.PI / 2, yaw: 0, roll: 0 };
    if (type === 'bow') return { pitch: 0.04, yaw: Math.PI / 2, roll: -0.04 };
    return { pitch: 0, yaw: Math.PI / 2, roll: 0 };
