    } else if (type === 'flamethrower') {
        base.position.set(0.22, -0.44, -0.92);
        base.rotation.set(0.04, -Math.PI / 2, -0.05);
        base.scale = 0.68;
    } else if (type === 'laser') {
        base.position.set(0.22, -0.44, -0.92);
        base.rotation.set(0.04, -Math.PI / 2, -0.05);
        base.scale = 0.68;
    } else if (type === 'pistol') {
        base.position.set(0.2, -0.42, -0.82);
        base.rotation.set(0.05, -Math.PI / 2, -0.02);
        base.scale = 0.76;
    } else if (type === 'rifle') {
