        const hit = { hit: true, direction, range: this.range, projSpeed };

        if (this.type === 'flamethrower') {
            const flames = [];
            const count = this.getProfile().flameCount || 3;
            for (let i = 0; i < count; i++) {
                const fd = direction.clone();
                fd.x += (Math.random() - 0.5) * 0.25;
                fd.y += (Math.random() - 0.5) * 0.25;
                fd.z += (Math.random() - 0.5) * 0.25;
